function fileDialog(p){openModal(modalHead('Anexar comprovante')+`<p class="subtitle">Recibo assinado ou nota fiscal de ${esc(p.data.recipient)} (${brl(p.data.value)}).</p><form id="adm-form" data-kind="pagamento-arquivo" data-id="${p.id}"><label class="field"><span>Arquivo (foto ou PDF)</span><input name="file" type="file" accept="image/*,application/pdf" required></label><p class="form-error" role="alert"></p><button class="button" type="submit">${icon('upload')}Enviar</button></form>`)}
async function uploadProof(payId,file){if(!file||!file.size)return null;if(file.size>15*1024*1024){toast('Arquivo muito grande (máximo de 15 MB).');return null}const ext=(file.name.split('.').pop()||'bin').toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,5)||'bin',path=`${payId}/${Date.now()}.${ext}`;
 const {error}=await sb.storage.from('comprovantes').upload(path,file,{contentType:file.type||undefined,upsert:false});if(error){toast(/bucket|not found/i.test(error.message)?'Falta atualizar o banco: execute supabase/administrativo.sql.':'Não foi possível enviar o arquivo: '+error.message);return null}return {file:path,fileName:file.name}}
// Recibo único por pagamento, no modelo da sala (Recibo de Pagamento SPIFF).
const RECEIPT_DEFAULTS={payer:'GAV RESORTS GESTAO DE NEGOCIOS E PARTICIPACAO LTDA',payerDoc:'40.831.644/00017-03',city:'Tibau do Sul'};
function receiptHtml(p){const c=admById(p.data.caixa),cd={...RECEIPT_DEFAULTS,...Object.fromEntries(Object.entries(c?.data||{}).filter(([k,v])=>['payer','payerDoc','city'].includes(k)&&v))},d=p.data,v=brl(d.value).replace(/\s/g,''),[y,m,dd]=String(d.date||today()).split('-'),mes=new Date(Number(y),Number(m)-1,1).toLocaleDateString('pt-BR',{month:'long'}),logo=RECEIPT_LOGO;
 return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Recibo de Pagamento — ${esc(d.recipient)}</title><style>@page{size:A4;margin:14mm}*{box-sizing:border-box}body{font-family:Arial,Helvetica,sans-serif;color:#1d1d1f;margin:0;padding:18px;background:#fff}
 .rec{border:1px solid #9aa3ad;padding:26px 30px 34px;max-width:760px;margin:0 auto}.top{display:grid;grid-template-columns:150px 1fr 150px;align-items:center;gap:12px}.top img{width:140px;border-radius:4px}.top h1{font-weight:400;font-size:24px;text-align:center;margin:0;line-height:1.2}.valor{border:1px solid #1d1d1f;padding:5px 10px;font-weight:700;font-size:14px;text-align:center;justify-self:end;min-width:120px}
 p{font-size:13.5px;line-height:1.55;margin:22px 0 0;text-align:justify}.pago{margin-top:18px}.data{text-align:right;margin-top:16px;color:#333}.sign{margin:54px auto 0;width:60%;border-top:1px solid #1d1d1f;text-align:center;padding-top:6px;font-size:12.5px}.no-print{text-align:center;margin-top:24px}.no-print button{font:600 14px Arial;padding:10px 18px;border:0;border-radius:8px;background:#0b306b;color:#fff;cursor:pointer}@media print{.no-print{display:none}body{padding:0}}</style></head><body>
 <div class="rec"><div class="top"><img src="${logo}" alt="GAV Hotéis e Resorts"><h1>Recibo de<br>Pagamento</h1><div class="valor">${v}</div></div>
 <p>Recebi(emos) de <b>${esc(cd.payer)}</b> - CPF/CNPJ nº <b>${esc(cd.payerDoc)}</b>, a importância de <b>${v}</b> referente a <b>${esc(String(d.action||'').toUpperCase())}</b>. Para maior clareza firmo(amos) o presente recibo para que produza os seus efeitos, dando plena, rasa e irrevogável quitação, pelo valor recebido.</p>
 <p class="pago">Pagamento recebido <b>${esc(String(d.recipient||'').toUpperCase())}</b>${d.recipientDoc?` - CPF/CNPJ: ${esc(d.recipientDoc)}`:''}</p>
 <p class="data">${esc(cd.city)}, ${Number(dd)} de ${mes} de ${y}</p>
 <div class="sign">${esc(d.recipient||'')}</div></div>
 <div class="no-print"><button onclick="window.print()">Imprimir</button></div><script>window.onload=()=>setTimeout(()=>window.print(),400)<\/script></body></html>`}
function printReceipt(p){const w=window.open('','_blank');if(!w){toast('Libere as janelas do navegador para imprimir o recibo.');return}w.document.write(receiptHtml(p));w.document.close()}
async function openProof(p){const w=window.open('','_blank');const {data,error}=await sb.storage.from('comprovantes').createSignedUrl(p.data.file,600);if(error||!data?.signedUrl){w?.close();toast('Não foi possível abrir o comprovante.');return}if(w)w.location=data.signedUrl;else location.href=data.signedUrl}
function exportCash(){const c=cashes().find(x=>x.id===view.cash)||cashes()[0];if(!c)return;const m=view.cashMonth||today().slice(0,7),s=cashSummary(c,m),cell=v=>`"${String(v??'').replace(/"/g,'""')}"`,team=id=>(c.data.teams||[]).find(t=>t.id===id)?.name||'';
 const rows=[['Caixa','Mês','Data','Equipe','Recebeu','Referente a','Valor','Situação','Lançado por','Comprovante'],...s.ps.slice().reverse().map(p=>[c.data.name,monthLabel(m),dateBR(p.data.date),team(p.data.team),p.data.recipient,p.data.action,Number(p.data.value||0).toFixed(2).replace('.',','),p.data.status==='pago'?'Pago':'Lançado',p.created_by_name,p.data.file?'Sim':'Não']),[],['Resumo'],['Recebido no mês','','','','','',s.budget.toFixed(2).replace('.',',')],['Pago','','','','','',s.spent.toFixed(2).replace('.',',')],['Saldo','','','','','',s.left.toFixed(2).replace('.',',')],...s.teams.length>1?s.teams.map(t=>[`Saldo ${t.name}`,'','','','','',t.left.toFixed(2).replace('.',',')]):[]];
 const csv=rows.map(r=>r.map(cell).join(';')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['﻿'+csv],{type:'text/csv;charset=utf-8'}));a.download=`caixa-${c.data.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}-${m}.csv`;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);toast('Planilha do mês exportada.')}
function oCashConfig(){if(!isManager())return '';const list=cashes();return `${backLabel('Caixas')}`+pageHead('Administrativo','Configurar caixas','Cada caixa tem uma ou mais equipes, cada uma com o valor que recebe por mês. O analista vê o saldo e lança os pagamentos.',headBtn('adm-cash-new','Novo caixa'))+admNotice()+`
 ${list.length?`<div class="card-grid">${list.map(c=>`<article class="assign-card${c.data.active===false?' paused':''}"><h3>${esc(c.data.name)}</h3><p class="assign-text">${(c.data.teams||[]).map(t=>`${esc(t.name)}: ${brl(t.amount)}`).join(' · ')}</p><p class="micro">Total por mês: ${brl((c.data.teams||[]).reduce((s,t)=>s+Number(t.amount||0),0))} · recibo em nome de ${esc(c.data.payer||RECEIPT_DEFAULTS.payer)}</p>${c.data.active===false?'<div class="chip-row"><span class="chip warn">Desativado</span></div>':''}<div class="assign-actions"><button class="text-btn" data-action="adm-cash-edit" data-id="${c.id}">Editar</button><button class="text-btn danger-text" data-action="adm-cash-del" data-id="${c.id}">Excluir</button></div></article>`).join('')}</div>`:`<div class="empty">${icon('wallet')}Nenhum caixa ainda.</div><button class="button" data-action="adm-cash-seed">${icon('plus')}Criar os caixas da sala</button>`}`}
const teamRow=t=>`<div class="team-row" data-id="${esc(t.id||crypto.randomUUID())}"><input name="teamName" required maxlength="60" placeholder="Nome da equipe" value="${esc(t.name||'')}" aria-label="Nome da equipe"><input name="teamAmount" inputmode="decimal" required placeholder="Valor por mês" value="${t.amount!=null&&t.amount!==''?esc(Number(t.amount).toFixed(2).replace('.',',')):''}" aria-label="Valor por mês"><button type="button" class="icon-btn danger" data-action="adm-team-del" aria-label="Remover equipe">${icon('trash')}</button></div>`;
function cashDialog(c){const d=c?.data||{teams:[{name:'Geral',amount:''}],active:true,...RECEIPT_DEFAULTS};openModal(modalHead(c?'Editar caixa':'Novo caixa')+`<form id="adm-form" data-kind="caixa" data-id="${c?.id||''}" autocomplete="off"><label class="field"><span>Nome do caixa</span><input name="name" required maxlength="60" value="${esc(d.name||'')}" placeholder="Ex.: Caixa SPIF"></label>
 <div class="field"><span>Equipes e valor por mês</span><div id="team-rows">${(d.teams||[]).map(teamRow).join('')}</div><button type="button" class="text-btn" data-action="adm-team-add">${icon('plus')}Adicionar equipe</button><small class="muted">Caixa sem divisão: deixe uma equipe só (ex.: “Geral”).</small></div>
 <label class="field"><span>Recibo: quem paga</span><input name="payer" maxlength="140" value="${esc(d.payer||RECEIPT_DEFAULTS.payer)}"></label><div class="field-grid"><label class="field"><span>CPF/CNPJ de quem paga</span><input name="payerDoc" maxlength="30" value="${esc(d.payerDoc||RECEIPT_DEFAULTS.payerDoc)}"></label><label class="field"><span>Cidade no recibo</span><input name="city" maxlength="60" value="${esc(d.city||RECEIPT_DEFAULTS.city)}"></label></div>
 <label class="check-row"><input type="checkbox" name="active" ${d.active!==false?'checked':''}><span>Ativo<small>Desativado some para o analista.</small></span></label>
 <p class="form-error" role="alert"></p><button class="button" type="submit">Salvar</button></form>`)}
async function seedCashes(){const id=()=>crypto.randomUUID();const a=await admSave('caixa',{name:'Caixa SPIF',teams:[['Captação A',1000],['Captação B',1000],['Consultoria A',1000],['Consultoria B',1000]].map(([name,amount])=>({id:id(),name,amount})),...RECEIPT_DEFAULTS,active:true});if(!a)return;await admSave('caixa',{name:'Caixa administrativo',teams:[{id:id(),name:'Geral',amount:1500}],...RECEIPT_DEFAULTS,active:true});view.cash=a.id;render();toast('Caixas criados. Ajuste nomes e valores em Configurar.')}

/* ---------- Ações ---------- */
async function admAction(a,b){const id=b.dataset.id,x=id&&admById(id);
 if(a==='adm-new-person'){closeModal();asgDialog(null,b.dataset.role);return}
 if(OFFICE_PAGES[a]){navigate(a,a==='o-order'?{order:id}:{});return}
 if(a==='adm-day'){view.admDay=addDays(view.admDay||today(),Number(b.dataset.step));render();return}
 if(a==='adm-done'){await toggleDone(b.dataset.task,b.dataset.date);return}
 if(a==='adm-task-new')return taskDialog();if(a==='adm-task-edit'&&x)return taskDialog(x);
 if(a==='adm-task-pause'&&x){if(await admSave('tarefa',{...x.data,active:x.data.active===false},x.id)){render();toast(x.data.active===false?'Tarefa retomada.':'Tarefa pausada.')}return}
 if(a==='adm-task-del'&&x)return confirmDialog(`Excluir “${x.data.title}”?`,'A tarefa some do cronograma. O que já foi feito continua registrado.','Excluir tarefa',async()=>{if(await admRemove(x.id)){closeModal();render();toast('Tarefa excluída.')}});
 if(a==='adm-ticket-tab'){view.ticketTab=b.dataset.tab;render();return}
 if(a==='adm-ticket-new')return ticketDialog();if(a==='adm-ticket-edit'&&x)return ticketDialog(x);
 if(a==='adm-ticket-toggle'&&x){const done=x.data.status!=='feito';if(await admSave('chamado',{...x.data,status:done?'feito':'aberto',doneAt:done?today():null,doneBy:done?me().name:null},x.id)){render();toast(done?'Chamado finalizado.':'Chamado reaberto.')}return}
 if(a==='adm-ticket-del'&&x)return confirmDialog(`Excluir o chamado ${x.data.number}?`,'O registro some da lista.','Excluir chamado',async()=>{if(await admRemove(x.id)){closeModal();render()}});
 if(a==='adm-ticket-copy'){if(!ticketsOpen().length){toast('Nenhum chamado em aberto para copiar.');return}const ok=await copyText(ticketCopyText());toast(ok?'Lista de chamados copiada. É só colar.':'Não foi possível copiar neste aparelho.');return}
 if(a==='adm-note-type'){view.noteType=b.dataset.type;render();return}
 if(a==='adm-note-month'){view.noteMonth=shiftMonth(view.noteMonth||today().slice(0,7),Number(b.dataset.step));render();return}
 if(a==='adm-note')return noteDialog(b.dataset.partner);
 if(a==='adm-note-del'&&x)return confirmDialog('Apagar o registro deste mês?','As datas desta nota serão apagadas.','Apagar',async()=>{if(await admRemove(x.id)){closeModal();render()}});
 if(a==='adm-partner-new')return partnerDialog();if(a==='adm-partner-edit'&&x)return partnerDialog(x);
 if(a==='adm-partner-del'&&x){const used=admOf('nota').some(n=>n.data.partner===x.id);return confirmDialog(`Excluir ${x.data.name}?`,used?'Este parceiro já tem notas registradas. Para manter o histórico, prefira editar e marcar como inativo.':'O parceiro sai da lista.',used?'Excluir mesmo assim':'Excluir',async()=>{if(await admRemove(x.id)){closeModal();render()}})}
 if(a==='adm-order-new')return orderDialog();if(a==='adm-order-edit'&&x)return orderDialog(x);
 if(a==='adm-order-del'&&x)return confirmDialog('Excluir este pedido?','O registro e os comentários serão apagados.','Excluir pedido',async()=>{if(await admRemove(x.id)){navigate('o-orders')}});
 if(a==='adm-order-resolve'&&x){const r=!x.data.resolved;if(await admSave('pedido',{...x.data,resolved:r,resolvedAt:r?today():null,comments:[...(x.data.comments||[]),{at:new Date().toISOString(),by:me().name,text:r?'Marcou como resolvido.':'Reabriu a pendência.'}]},x.id)){render();toast(r?'Pendência resolvida.':'Pendência reaberta.')}return}
 if(a==='adm-cash-tab'){view.cash=id;render();return}
 if(a==='adm-cash-month'){view.cashMonth=shiftMonth(view.cashMonth||today().slice(0,7),Number(b.dataset.step));render();return}
 if(a==='adm-cash-seed')return seedCashes();if(a==='adm-cash-new')return cashDialog();if(a==='adm-cash-edit'&&x)return cashDialog(x);
 if(a==='adm-cash-del'&&x){const used=admOf('pagamento').some(p=>p.data.caixa===x.id);return confirmDialog(`Excluir ${x.data.name}?`,used?'Este caixa tem pagamentos lançados. Para manter a prestação de contas, prefira desativar.':'O caixa sai da lista.',used?'Excluir mesmo assim':'Excluir',async()=>{if(await admRemove(x.id)){closeModal();render()}})}
 if(a==='adm-team-add'){document.getElementById('team-rows')?.insertAdjacentHTML('beforeend',teamRow({}));document.querySelector('#team-rows .team-row:last-child input')?.focus();return}
 if(a==='adm-team-del'){const rows=document.querySelectorAll('#team-rows .team-row');if(rows.length<2){toast('O caixa precisa de pelo menos uma equipe.');return}b.closest('.team-row')?.remove();return}
 if(a==='adm-pay-new')return payDialog();if(a==='adm-pay-edit'&&x)return payDialog(x);
 if(a==='adm-pay-receipt'&&x)return printReceipt(x);
 if(a==='adm-pay-file'&&x)return fileDialog(x);if(a==='adm-pay-file-open'&&x)return openProof(x);
 if(a==='adm-pay-paid'&&x){if(await admSave('pagamento',{...x.data,status:'pago'},x.id)){render();toast('Pagamento marcado como pago.')}return}
 if(a==='adm-pay-del'&&x)return confirmDialog(`Excluir o pagamento de ${brl(x.data.value)}?`,`${x.data.recipient} · ${x.data.action||''}. O valor volta para o saldo.`,'Excluir pagamento',async()=>{if(await admRemove(x.id)){closeModal();render()}});
 if(a==='adm-cash-export')return exportCash();
 if(a==='adm-contract-month'){view.contractMonth=shiftMonth(view.contractMonth||today().slice(0,7),Number(b.dataset.step));render();return}
 if(a==='adm-contract-filter'){view.contractFilter=b.dataset.f;render();return}
 if(a==='adm-contract-new')return contractDialog();if(a==='adm-contract-open'&&x)return contractView(x);if(a==='adm-contract-edit'&&x)return contractDialog(x);
 if(a==='adm-contract-audit'&&x){if(x.data.lancamento?.id===authId&&!isManager()){toast('Quem lançou não audita o próprio contrato.');return}return auditDialog(x)}
 if(a==='adm-contract-del'&&x)return confirmDialog(`Excluir o contrato de ${x.data.cliente}?`,'O lançamento e a auditoria serão apagados.','Excluir contrato',async()=>{if(await admRemove(x.id)){closeModal();render()}});
 if(a==='adm-contract-export')return exportContracts()}

/* ---------- Formulários ---------- */
async function admSubmit(form,f,err){const kind=form.dataset.kind,id=form.dataset.id||null,x=id&&admById(id),btn=form.querySelector('button[type=submit]'),str=k=>String(f.get(k)??'').trim(),done=msg=>{closeModal();render();if(msg)toast(msg)};
 const lock=on=>{if(btn)btn.disabled=on};
 if(kind==='tarefa'){const r=readRepeat(form.querySelector('.repeat-box'));if(r.repeat.type==='weekly'&&!r.repeat.weekdays.length)return err('Escolha pelo menos um dia da semana.');if(r.end&&r.end<r.start)return err('O término deve ser depois do início.');const assignees=f.getAll('assignees');if(!assignees.length)return err('Escolha quem faz a tarefa.');
  lock(true);const ok=await admSave('tarefa',{...(x?.data||{}),title:str('title'),notes:str('notes'),assignees,...r,active:x?.data.active!==false},id);lock(false);if(ok)done(id?'Tarefa atualizada.':'Tarefa criada.');return}
 if(kind==='chamado'){if(!str('number'))return err('Informe o número do chamado.');const dup=admOf('chamado').find(t=>t.id!==id&&String(t.data.number).trim().toLowerCase()===str('number').toLowerCase());if(dup)return err(`O chamado ${str('number')} já está registrado.`);
  lock(true);const ok=await admSave('chamado',{...(x?.data||{status:'aberto'}),number:str('number'),openedAt:str('openedAt')||today(),description:str('description')},id);lock(false);if(ok){if(!id)view.ticketTab='open';done(id?'Chamado atualizado.':'Chamado registrado.')}return}
 if(kind==='parceiro'){if(!str('name'))return err('Informe o nome.');const t=str('type')||'parceiro';if(admOf('parceiro').some(p=>p.id!==id&&(p.data.type||'parceiro')===t&&p.data.name.toLowerCase()===str('name').toLowerCase()))return err('Já existe com este nome.');
  lock(true);const ok=await admSave('parceiro',{name:str('name'),type:t,info:str('info'),active:f.get('active')==='on'},id);lock(false);if(ok)done(id?'Cadastro atualizado.':'Parceiro cadastrado.');return}
 if(kind==='nota'){const old=x?.data.steps||{},steps={},who=me().name,v=str('value')?parseMoney(str('value')):null;if(str('value')&&!Number.isFinite(v))return err('Valor inválido.');
  for(const [k] of NOTE_STEPS){const date=str(k)||null,prev=old[k]||{};steps[k]=date?{...prev,date,by:prev.date===date&&prev.by?prev.by:who}:null;if(k==='pagamento'&&steps[k])steps[k].done=f.get('paid')==='on'}
  if(f.get('paid')==='on'&&!steps.pagamento)return err('Informe a data do pagamento.');
  lock(true);const ok=await admSave('nota',{partner:form.dataset.partner,month:form.dataset.month,type:admById(form.dataset.partner)?.data.type||'parceiro',number:str('number'),value:v,obs:str('obs'),steps},id);lock(false);if(ok)done('Nota atualizada.');return}
 if(kind==='pedido'){if(!/^\d{4}-\d{2}$/.test(str('month')))return err('Informe o mês do pedido.');const status=str('status');if(status==='nao_conforme'&&!str('issues'))return err('Descreva o que faltou ou veio errado.');
  lock(true);const ok=await admSave('pedido',{...(x?.data||{comments:[]}),month:str('month'),title:str('title'),arrivedAt:str('arrivedAt')||null,invoiceAt:str('invoiceAt')||null,zeevAt:str('zeevAt')||null,status,issues:str('issues'),resolved:status==='nao_conforme'?!!x?.data.resolved:false},id);lock(false);if(ok){closeModal();navigate('o-order',{order:ok.id});toast(id?'Pedido atualizado.':'Pedido registrado.')}return}
 if(kind==='pedido-comentario'){if(!x||!str('text'))return;lock(true);const ok=await admSave('pedido',{...x.data,comments:[...(x.data.comments||[]),{at:new Date().toISOString(),by:me().name,text:str('text')}]},id);lock(false);if(ok){render();toast('Comentário registrado.')}return}
 if(kind==='caixa'){const rows=[...form.querySelectorAll('.team-row')].map(r=>({id:r.dataset.id,name:r.querySelector('[name=teamName]').value.trim(),amount:parseMoney(r.querySelector('[name=teamAmount]').value)}));if(!str('name'))return err('Informe o nome do caixa.');if(!rows.length)return err('Adicione pelo menos uma equipe.');if(rows.some(t=>!t.name||!Number.isFinite(t.amount)||t.amount<0))return err('Confira o nome e o valor de cada equipe.');
  lock(true);const ok=await admSave('caixa',{name:str('name'),teams:rows,payer:str('payer')||RECEIPT_DEFAULTS.payer,payerDoc:str('payerDoc')||RECEIPT_DEFAULTS.payerDoc,city:str('city')||RECEIPT_DEFAULTS.city,active:f.get('active')==='on'},id);lock(false);if(ok){view.cash=ok.id;done(id?'Caixa atualizado.':'Caixa criado.')}return}
 if(kind==='pagamento'){const v=parseMoney(str('value'));if(!Number.isFinite(v)||v<=0)return err('Informe um valor válido.');if(!str('team'))return err('Escolha a equipe.');if(!str('recipient'))return err('Informe quem recebeu.');
  lock(true);let ok=await admSave('pagamento',{...(x?.data||{}),caixa:form.dataset.caixa,month:form.dataset.month,team:str('team'),recipient:str('recipient'),recipientDoc:str('recipientDoc'),value:v,date:str('date'),action:str('action'),status:str('status')||'lancado'},id);
  const file=form.querySelector('input[type=file]')?.files?.[0];if(ok&&file){const up=await uploadProof(ok.id,file);if(up)ok=await admSave('pagamento',{...ok.data,...up},ok.id)||ok}lock(false);
  if(ok){const c=admById(form.dataset.caixa),left=c?cashSummary(c,form.dataset.month).teams.find(t=>t.id===str('team'))?.left:null;done(left!=null&&left<0?`Pagamento salvo. Atenção: a equipe ficou com saldo negativo (${brl(left)}).`:id?'Pagamento atualizado.':'Pagamento lançado. Use “Recibo” para imprimir e colher a assinatura.')}return}
 if(kind==='contrato'){if(!str('cliente'))return err('Informe o cliente.');const launch=str('lancamento').toUpperCase(),mine=launch===me().name.toUpperCase();
  lock(true);const ok=await admSave('contrato',{...(x?.data||{}),cliente:str('cliente').toUpperCase(),aprovador:str('aprovador').toUpperCase(),dataVenda:str('dataVenda'),turno:str('turno')||'DIURNO',cotas:Math.max(1,Number(str('cotas'))||1),lancamento:{name:launch,id:mine?authId:(x?.data.lancamento?.name===launch?x.data.lancamento.id||null:null)}},id);lock(false);if(ok){view.contractMonth=ok.data.dataVenda.slice(0,7);done(id?'Contrato atualizado.':'Contrato lançado. Agora outra pessoa faz a auditoria.')}return}
 if(kind==='contrato-auditoria'){if(!x)return;const checks={};for(const [k,lb] of AUDIT_CHECKS){const level=str('lv-'+k)||'ok',note=str('note-'+k),value=str('val-'+k);if((level==='medio'||level==='grave')&&!note)return err(`Descreva o erro em “${lb}”.`);checks[k]={level,note,...(value?{value}:{})}}
  lock(true);const ok=await admSave('contrato',{...x.data,checks,audit:{date:x.data.audit?.date||today(),by:me().name.toUpperCase(),byId:authId}},id);lock(false);if(ok){const l=contractLevel(ok);done(l==='grave'?'Auditoria salva: contrato com erro vermelho.':l==='medio'?'Auditoria salva: contrato com erro amarelo.':'Auditoria salva: contrato verde.')}return}
 if(kind==='pagamento-arquivo'){const file=form.querySelector('input[type=file]')?.files?.[0];if(!x||!file)return err('Escolha o arquivo.');lock(true);const up=await uploadProof(x.id,file);const ok=up&&await admSave('pagamento',{...x.data,...up},x.id);lock(false);if(ok)done('Comprovante anexado.');return}}

/* ---------- Usuários do administrativo ---------- */
function officeTile(u){return `<button class="tile" data-action="edit-asg" data-id="${esc(u.id)}"><span class="tile-icon"><span class="avatar-lg">${esc(initials(u.name))}</span></span><span class="grow"><strong>${esc(u.name)}</strong><span class="muted">${esc(ROLE_NAMES[u.role].replace(/^./,c=>c.toUpperCase()))}${u.active?'':' · inativo'}</span><span class="muted">${esc(u.email)}</span></span>${icon('edit','chevron')}</button>`}
function officeRoleDialog(){openModal(modalHead('Cadastrar no administrativo')+`<p class="subtitle">Escolha a função. Cada uma vê só a própria parte.</p><div class="role-choice">${OFFICE_ROLES.map(r=>`<button class="tile" data-action="adm-new-person" data-role="${r}"><span class="tile-icon">${icon(r==='analista'?'wallet':'ticket')}</span><span class="grow"><strong>${ROLE_NAMES[r].replace(/^./,c=>c.toUpperCase())}</strong><span class="muted">${r==='analista'?'Cronograma, notas fiscais, pedidos e caixas':'Cronograma, chamados e auditoria de contratos'}</span></span>${icon('chevron','chevron')}</button>`).join('')}</div>`)}
{const base=signOutLocal;signOutLocal=async function(...a){adm=[];admError='';return base(...a)}}

/* ---------- Auditoria de contratos (assistente de contratos) ---------- */
// Mesmas colunas da planilha da sala. Cada item conferido tem cor: verde (certo), amarelo (erro mediano, talvez não venha)
// e vermelho (erro que vai ou corre muito risco de ser pontuado para a sala).
const AUDIT_CHECKS=[['erro','Erro'],['boletos','Boletos'],['uau','Documentação UAU'],['crm','CRM'],['flow','Flow']];
const LEVELS={ok:['Verde','Tudo certo'],medio:['Amarelo','Erro mediano, talvez não venha'],grave:['Vermelho','Erro que vai ou corre risco de vir'],na:['Não se aplica','']};
const LEVEL_RANK={grave:3,medio:2,ok:1,na:0};
const contractLevel=c=>{if(!c.data.audit)return 'pendente';let w='ok';for(const [k] of AUDIT_CHECKS){const l=c.data.checks?.[k]?.level;if(l&&LEVEL_RANK[l]>LEVEL_RANK[w])w=l}return w};
const contractsOf=m=>admOf('contrato').filter(c=>String(c.data.dataVenda||'').slice(0,7)===m).sort((a,b)=>String(a.data.dataVenda).localeCompare(b.data.dataVenda)||String(a.created_at).localeCompare(b.created_at));
const levelDot=(l,txt)=>`<span class="lv dot-${l||'none'}" title="${esc(LEVELS[l]?.[0]||'Não conferido')}">${txt??''}</span>`;
const checkText=(c,k)=>{const x=c.data.checks?.[k];if(!c.data.audit||!x)return '';return x.note||x.value||(x.level==='na'?'Não se aplica':x.level==='ok'?(k==='flow'?'Sim':'OK'):'')};
const peopleSuggest=()=>[...new Set([...admOf('contrato').flatMap(c=>[c.data.aprovador,c.data.lancamento?.name,c.data.audit?.by]),...officePeople().map(u=>u.name)].filter(Boolean).map(x=>String(x).trim().toUpperCase()))].sort();
function oContracts(){const m=view.contractMonth||today().slice(0,7),all=contractsOf(m),filt=view.contractFilter||'all',q=(view.contractQuery||'').trim().toUpperCase(),lv=all.map(contractLevel),count=k=>lv.filter(x=>x===k).length;
 const list=all.filter((c,i)=>(filt==='all'||lv[i]===filt)&&(!q||String(c.data.cliente).toUpperCase().includes(q)));
 const chip=(k,label,cls)=>`<button class="lv-filter ${cls}${filt===k?' on':''}" data-action="adm-contract-filter" data-f="${k}" aria-pressed="${filt===k}"><b>${k==='all'?all.length:count(k)}</b>${label}</button>`;
 return (isManager()?sectorTabs('adm'):'')+pageHead('Administrativo','Auditoria de contratos','Quem lança registra o contrato; outra pessoa audita e marca cada item: verde, amarelo ou vermelho.',`<div class="head-actions"><button class="text-btn" data-action="adm-contract-export">${icon('download')}Exportar mês</button>${headBtn('adm-contract-new','Lançar contrato')}</div>`)+admNotice()+`
 ${monthNav(m,'adm-contract-month')}
 <div class="lv-filters">${chip('all','contratos','')}${chip('pendente','aguardando auditoria','pend')}${chip('grave','vermelhos','grave')}${chip('medio','amarelos','medio')}${chip('ok','verdes','ok')}</div>
 <p class="micro">${all.reduce((s,c)=>s+Number(c.data.cotas||0),0)} cotas no mês · ${all.length-count('pendente')} de ${all.length} auditados</p>
 <div class="search">${icon('search')}<input id="contract-search" type="search" value="${esc(view.contractQuery||'')}" placeholder="Buscar cliente" aria-label="Buscar cliente"></div>
 ${list.length?`<div class="table-wrap contract-table-wrap"><table class="contract-table"><thead><tr><th>Cliente</th><th>Aprovador</th><th>Venda</th><th>Turno</th><th>Cotas</th><th>Lançamento</th><th>Auditado</th><th>Data aud.</th>${AUDIT_CHECKS.map(([k,l])=>`<th>${l}</th>`).join('')}<th>Auditoria por</th></tr></thead><tbody>${list.map(c=>{const d=c.data,a=d.audit;return `<tr data-action="adm-contract-open" data-id="${c.id}" class="row-${contractLevel(c)}"><td class="cl">${esc(d.cliente)}</td><td>${esc(d.aprovador||'')}</td><td>${dateBR(d.dataVenda)}</td><td>${esc(d.turno||'')}</td><td class="num">${esc(d.cotas||'')}</td><td>${esc(d.lancamento?.name||'')}</td><td>${a?'<b class="ok-text">SIM</b>':'<span class="pending-text">NÃO</span>'}</td><td>${a?dateBR(a.date):''}</td>${AUDIT_CHECKS.map(([k])=>{const l=a?d.checks?.[k]?.level:null;return `<td class="ck ck-${l||'none'}">${esc(checkText(c,k))}</td>`}).join('')}<td>${esc(a?.by||'')}</td></tr>`}).join('')}</tbody></table></div>
 <div class="contract-cards">${list.map(c=>{const d=c.data,l=contractLevel(c);return `<button class="contract-card lvl-${l}" data-action="adm-contract-open" data-id="${c.id}"><span class="grow"><strong>${esc(d.cliente)}</strong><small>${dateBR(d.dataVenda)} · ${esc(d.turno||'')} · ${plural(Number(d.cotas||0),'cota','cotas')} · lançado por ${esc(d.lancamento?.name||'—')}</small><span class="lv-row">${d.audit?AUDIT_CHECKS.map(([k,lb])=>`<span class="lv-item">${levelDot(d.checks?.[k]?.level)}${lb}</span>`).join(''):'<span class="pending-text">Aguardando auditoria</span>'}</span></span>${icon('chevron','chevron')}</button>`}).join('')}</div>`
 :`<div class="empty">${icon('file')}${all.length?'Nenhum contrato neste filtro.':`Nenhum contrato lançado em ${monthLabel(m).toLowerCase()}.`}</div>`}
 <datalist id="people-list">${peopleSuggest().map(n=>`<option value="${esc(n)}">`).join('')}</datalist>`}
function contractDialog(c){const d=c?.data||{dataVenda:today(),turno:spHour()<15?'DIURNO':'NOTURNO',cotas:1,lancamento:{name:me().name.toUpperCase(),id:authId}};
 openModal(modalHead(c?'Editar contrato':'Lançar contrato')+`<form id="adm-form" data-kind="contrato" data-id="${c?.id||''}" autocomplete="off"><label class="field"><span>Cliente</span><input name="cliente" required maxlength="140" value="${esc(d.cliente||'')}"></label>
 <div class="field-grid"><label class="field"><span>Aprovador</span><input name="aprovador" list="people-list-d" maxlength="80" value="${esc(d.aprovador||'')}"></label><label class="field"><span>Responsável pelo lançamento</span><input name="lancamento" list="people-list-d" required maxlength="80" value="${esc(d.lancamento?.name||'')}"></label></div>
 <div class="field-grid">${dateInput('dataVenda',d.dataVenda,'Data da venda',true)}<label class="field"><span>Quantidade de cotas</span><input name="cotas" type="number" min="1" max="99" required value="${esc(d.cotas||1)}"></label></div>
 <div class="field"><span>Turno</span><div class="role-pick"><label class="radio-card"><input type="radio" name="turno" value="DIURNO" ${d.turno!=='NOTURNO'?'checked':''}><span><strong>Diurno</strong></span></label><label class="radio-card"><input type="radio" name="turno" value="NOTURNO" ${d.turno==='NOTURNO'?'checked':''}><span><strong>Noturno</strong></span></label></div></div>
 <datalist id="people-list-d">${peopleSuggest().map(n=>`<option value="${esc(n)}">`).join('')}</datalist><p class="form-error" role="alert"></p><button class="button" type="submit">Salvar</button></form>`)}
function contractView(c){const d=c.data,a=d.audit,l=contractLevel(c),own=d.lancamento?.id===authId&&!isManager();
 openModal(modalHead(d.cliente)+`<div class="contract-head lvl-${l}"><span>${l==='pendente'?'Aguardando auditoria':`Auditado em ${dateBR(a.date)} por ${esc(a.by)}`}</span>${l!=='pendente'?`<b>${LEVELS[l][0]}</b>`:''}</div>
 <dl class="order-facts contract-facts"><div><dt>Aprovador</dt><dd>${esc(d.aprovador||'—')}</dd></div><div><dt>Data da venda</dt><dd>${dateBR(d.dataVenda)}</dd></div><div><dt>Turno</dt><dd>${esc(d.turno||'—')}</dd></div><div><dt>Cotas</dt><dd>${esc(d.cotas||'—')}</dd></div><div><dt>Lançamento</dt><dd>${esc(d.lancamento?.name||'—')}</dd></div></dl>
 ${a?`<div class="check-list-view">${AUDIT_CHECKS.map(([k,lb])=>{const x=d.checks?.[k]||{};return `<div class="ckv ck-${x.level||'none'}"><strong>${lb}</strong><span>${esc(checkText(c,k)||'—')}</span></div>`}).join('')}</div>`:''}
 ${own&&!a?'<p class="micro">Você lançou este contrato. A auditoria é feita por outra pessoa.</p>':''}
 <div class="dialog-actions">${own?'':`<button class="button" data-action="adm-contract-audit" data-id="${c.id}">${icon('check')}${a?'Editar auditoria':'Auditar contrato'}</button>`}<button class="button outline" data-action="adm-contract-edit" data-id="${c.id}">${icon('edit')}Editar dados</button><button class="small-link danger-text" data-action="adm-contract-del" data-id="${c.id}">Excluir contrato</button></div>`)}
function auditDialog(c){const d=c.data,ck=d.checks||{};
 openModal(modalHead('Auditar contrato')+`<p class="subtitle">${esc(d.cliente)} · ${dateBR(d.dataVenda)} · ${plural(Number(d.cotas||0),'cota','cotas')} · lançado por ${esc(d.lancamento?.name||'—')}</p><form id="adm-form" data-kind="contrato-auditoria" data-id="${c.id}" autocomplete="off">
 ${AUDIT_CHECKS.map(([k,lb])=>{const x=ck[k]||{level:'ok'},opts=['ok','medio','grave',...(k==='boletos'||k==='flow'?['na']:[])];return `<fieldset class="audit-check"><legend>${lb}</legend><div class="lv-pick">${opts.map(o=>`<label class="lv-opt lv-${o}"><input type="radio" name="lv-${k}" value="${o}" ${x.level===o?'checked':''}><span>${LEVELS[o][0]}</span></label>`).join('')}</div>${k==='boletos'?`<div class="quick-vals">${['OK','ONLINE'].map(v=>`<label><input type="radio" name="val-${k}" value="${v}" ${(x.value||'OK')===v?'checked':''}><span>${v}</span></label>`).join('')}</div>`:''}${k==='flow'?`<div class="quick-vals">${['SIM','NÃO - MANUAL'].map(v=>`<label><input type="radio" name="val-${k}" value="${v}" ${(x.value||'SIM')===v?'checked':''}><span>${v}</span></label>`).join('')}</div>`:''}<input name="note-${k}" maxlength="400" placeholder="Descreva o erro (obrigatório no amarelo e no vermelho)" value="${esc(x.note||'')}"></fieldset>`}).join('')}
 <p class="micro">Verde: tudo certo · Amarelo: erro mediano, talvez não venha · Vermelho: erro que vai ou corre muito risco de ser pontuado para a sala.</p>
 <p class="form-error" role="alert"></p><button class="button" type="submit">${icon('check')}Salvar auditoria</button></form>`)}
function exportContracts(){const m=view.contractMonth||today().slice(0,7),rows=contractsOf(m);if(!rows.length){toast('Nenhum contrato neste mês.');return}const cell=v=>`"${String(v??'').replace(/"/g,'""')}"`;
 const head=['CLIENTE','APROVADOR','DATA DA VENDA','TURNO','QUANT. COTAS','RESPONSÁVEL DO LANÇAMENTO','AUDITADO','DATA DA AUDITORIA','ERRO','RESPONSÁVEL PELA AUDITORIA','BOLETOS','DOCUMENTAÇÃO UAU','CRM','FLOW','GRAVIDADE'];
 const csv=[head.map(cell).join(';'),...rows.map(c=>{const d=c.data,a=d.audit;return [d.cliente,d.aprovador,dateBR(d.dataVenda),d.turno,d.cotas,d.lancamento?.name,a?'SIM':'NÃO',a?dateBR(a.date):'',checkText(c,'erro'),a?.by||'',checkText(c,'boletos'),checkText(c,'uau'),checkText(c,'crm'),checkText(c,'flow'),{pendente:'',ok:'VERDE',medio:'AMARELO',grave:'VERMELHO'}[contractLevel(c)]].map(cell).join(';')})].join('\r\n');
 const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['﻿'+csv],{type:'text/csv;charset=utf-8'}));a.download=`auditoria-contratos-${m}.csv`;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);toast('Planilha do mês exportada.')}

document.addEventListener('input',e=>{if(e.target.id!=='contract-search')return;const pos=e.target.selectionStart;view.contractQuery=e.target.value;render();const f=document.getElementById('contract-search');if(f){f.focus();f.setSelectionRange(pos,pos)}});
// Logo do recibo (GAV Hotéis e Resorts), embutida para o recibo abrir em qualquer janela.
const RECEIPT_LOGO='data:image/jpeg;base64,';
